  const a = atom(0);
  const { result } = renderHook(() => useAtom(a));
  act(() => result.current[1](99));
  expect(result.current[0]).toBe(99);
});

test('setter with updater function works', () => {
  const a = atom(5);
  const { result } = renderHook(() => useAtom(a));
  act(() => result.current[1](prev => prev * 2));
  expect(result.current[0]).toBe(10);
