solution:
import { useSyncExternalStore, useCallback } from 'react';

export type Atom<T> = {
  get: () => T;
  set: (v: T) => void;
  subscribe: (fn: () => void) => () => void;
};

export function atom<T>(initial: T): Atom<T> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (v: T) => {
      value = v;
      listeners.forEach(fn => fn());
    },
    subscribe: (fn: () => void) => {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
  };
}

export function useAtom<T>(a: Atom<T>): [T, (v: T | ((prev: T) => T)) => void] {
  const value = useSyncExternalStore(a.subscribe, a.get);
  const setter = useCallback((v: T | ((prev: T) => T)) => {
    const next = typeof v === 'function' ? (v as (prev: T) => T)(a.get()) : v;
    a.set(next);
  }, [a]);
  return [value, setter];
}
